import sys
def main():
    d = sys.stdin.read().split(); k, T = int(d[0]), int(d[1]); coins = list(map(int, d[2:2+k]))
    INF = float('inf'); best = [0] + [INF] * T
    for x in range(1, T + 1):
        for c in coins:
            if c <= x and best[x - c] + 1 < best[x]: best[x] = best[x - c] + 1
    print(best[T] if best[T] != INF else -1)
main()
